mapper.update:
UPDATE catalog_product
SET name = #{name}, price = #{price}, stock = #{stock}, category = #{category}, description = #{description}
WHERE product_id = #{productId} AND deleted_at IS NULL

UPDATE catalog_product
SET stock = stock - #{quantity}
WHERE product_id = #{productId} AND deleted_at IS NULL
  AND #{quantity} > 0
  AND stock >= #{quantity}

UPDATE catalog_product
SET stock = stock + #{quantity}
WHERE product_id = #{productId}
  AND #{quantity} > 0
  AND deleted_at IS NULL

mapper.select:
SELECT product_id, name, price, stock, category, description, created_at FROM catalog_product
deleted_at IS NULL
AND name LIKE CONCAT('%', #{keyword}, '%')
AND category = #{category}
AND price >= #{minPrice}
AND price <= #{maxPrice}

SELECT product_id, name, price, stock, category, description, created_at FROM catalog_product
deleted_at IS NULL
AND name LIKE CONCAT('%', #{keyword}, '%')
AND category = #{category}
AND price >= #{minPrice}
AND price <= #{maxPrice}
AND product_id > #{afterProductId}
ORDER BY product_id ASC LIMIT #{limit}
